def transfer(self, sku: str, qty: int, source: str, dest: str) -> None:
    have = self.on_hand(sku, source)
    if qty > have:
        raise InsufficientStock(f"{sku}@{source}: need {qty}, have {have}")
    self.ship(sku, qty, source)
    self.receive(sku, qty, dest)
